 {cat="Dungeon",name="Set Normal",code='if SetDungeonDifficulty then SetDungeonDifficulty(1) end'},
 {cat="Dungeon",name="Set Heroic",code='if SetDungeonDifficulty then SetDungeonDifficulty(2) end'},
 {cat="UI",name="Reload UI",code='ReloadUI()'},
 {cat="UI",name="Frame under mouse",code='local f=GetMouseFocus(); print(f and (f:GetName() or tostring(f)) or "nil")'},
 {cat="Target",name="Target summary",code='print(UnitName("target"),UnitLevel("target"),UnitGUID("target"),UnitCreatureType("target"),UnitClassification("target"))'},
 {cat="Player",name="Player position basics",code='print(GetZoneText(),GetSubZoneText(),GetRealZoneText())'},
 {cat="Camera",name="Farclip 1000",code='SetCVar("farclip","1000")'},
