 {cat="Graphics",name="Enable script errors",code='SetCVar("scriptErrors","1")'},
 {cat="Inventory",name="Dump equipped item links",code='for i=1,19 do local l=GetInventoryItemLink("player",i); if l then print(i,l) end end'},
 {cat="Bags",name="Dump all bag items",code='for b=0,4 do for s=1,GetContainerNumSlots(b) do local l=GetContainerItemLink(b,s); if l then print(b,s,l) end end end'},
 {cat="Auras",name="Dump player buffs",code='for i=1,40 do local n=UnitBuff("player",i); if not n then break end print(i,n) end'},
