 {cat="Macros",name="Dump macros",code='local g,c=GetNumMacros(); print("global",g,"char",c); for i=1,g+c do local n,ic,b=GetMacroInfo(i); print(i,n,ic,b) end'},
 {cat="Performance",name="FPS and latency",code='local d,h,w=GetNetStats(); print("FPS",GetFramerate(),"latency",h,w)'},
 {cat="Addon",name="Addon memory",code='UpdateAddOnMemoryUsage(); for i=1,GetNumAddOns() do print(GetAddOnInfo(i),GetAddOnMemoryUsage(i)) end'},
