 {cat="Merchant",name="Dump merchant",code='for i=1,GetMerchantNumItems() do local n,t,p,q,num,usable,ext=GetMerchantItemInfo(i); print(i,n,p,q,num,usable,ext) end'},
 {cat="Quest",name="Dump quest log",code='for i=1,GetNumQuestLogEntries() do local t,l,tag,h,fold,comp=GetQuestLogTitle(i); print(i,t,l,tag,h,fold,comp) end'},
